package lint

import (
	"errors"
	"io/fs"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/c65llc/starboard/internal/diag"
	"github.com/c65llc/starboard/internal/generate"
	"github.com/c65llc/starboard/internal/project"
)

const (
	appMap    = "docs/flows/generated/app-map.md"
	screensMD = "docs/flows/generated/screens.md"
)

// fresh is the base project with its generated files written, and the
// generated files themselves.
func fresh(t *testing.T) (project.MemFS, map[string][]byte) {
	t.Helper()
	p := mkProject(t, base())
	gen := generate.All(p)
	require.Contains(t, gen, appMap)
	m := p.FS.(project.MemFS)
	for name, data := range gen {
		m[name] = data
	}
	return m, gen
}

func TestRule_generated_stale(t *testing.T) {
	r := rule(t, "generated-stale")
	assert.Equal(t, diag.Error, r.Default)

	m, gen := fresh(t)
	p, _, err := project.Load(m)
	require.NoError(t, err)
	assert.Empty(t, r.Run(p, &Context{Generated: gen}), "fresh")
	assert.Empty(t, r.Run(p, &Context{}), "nil Generated is not checked")

	m[appMap] = []byte("edited\n")
	delete(m, screensMD)
	m["docs/flows/generated/notes.md"] = []byte("mine\n")
	m["docs/flows/notes.md"] = []byte("outside generated/ is never considered\n")
	ds := r.Run(p, &Context{Generated: gen})
	require.Len(t, ds, 3)
	fix := &diag.Fix{Description: "run starboard generate"}
	assert.Equal(t, []diag.Diagnostic{
		{Rule: "generated-stale", File: appMap, Message: appMap + " is out of date", Fix: fix},
		{Rule: "generated-stale", File: "docs/flows/generated/notes.md",
			Message: "docs/flows/generated/notes.md is not generated by starboard; remove it", Fix: fix},
		{Rule: "generated-stale", File: screensMD, Message: screensMD + " is missing", Fix: fix},
	}, ds)
}

type failOpen struct {
	project.MemFS
	fail string
}

func (f failOpen) Open(name string) (fs.File, error) {
	if name == f.fail {
		return nil, errors.New("boom")
	}
	return f.MemFS.Open(name)
}

func TestRule_generated_stale_readError(t *testing.T) {
	m, gen := fresh(t)
	p, _, err := project.Load(m)
	require.NoError(t, err)
	p.FS = failOpen{MemFS: m, fail: "docs/flows/generated"}
	ds := rule(t, "generated-stale").Run(p, &Context{Generated: gen})
	require.Len(t, ds, 1)
	assert.Equal(t, "docs/flows/generated", ds[0].File)
	assert.Contains(t, ds[0].Message, "cannot check generated files: ")
	assert.Contains(t, ds[0].Message, "boom")
}

// TestRun_passesGenerated: Run hands Options.Generated to the rule.
func TestRun_passesGenerated(t *testing.T) {
	m, gen := fresh(t)
	delete(m, screensMD)
	p, ds, err := project.Load(m)
	require.NoError(t, err)
	stale := func(res Result) []string {
		var out []string
		for _, d := range res.Diagnostics {
			if d.Rule == "generated-stale" {
				out = append(out, d.File)
			}
		}
		return out
	}
	assert.Equal(t, []string{screensMD}, stale(Run(p, ds, Options{Generated: gen})))
	assert.Empty(t, stale(Run(p, ds, Options{})))
}
